<?php
namespace App\Http\Controllers;
use App\Models\{SeoActivity,SeoBacklinkActivity,SeoCampaign,SeoMonthlyCycle,SeoOnPageOptimization,SeoPerformanceRecord,SeoReport,SeoTechnicalIssue};
use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class SeoOperationsController extends Controller {
 public function dashboard(SeoCampaign $campaign){$this->authorize('view',$campaign);if($this->isClient())return redirect()->route('seo.workspace',[$campaign,'tab'=>'reports']);$k=$campaign->keywords()->count();$latest=$campaign->keywords()->with('latestRanking')->get();$top10=$latest->filter(fn($x)=>$x->latestRanking?->rank_position && $x->latestRanking->rank_position<=10)->count();return view('seo.operations.dashboard',compact('campaign','k','top10','latest'));}
 public function workspace(SeoCampaign $campaign,Request $request){$this->authorize('view',$campaign);$isClient=$this->isClient();$tab=$isClient?'reports':$request->get('tab','activities');$reports=$campaign->reports()->latest('period_end');if($isClient)$reports->where('status','published');$latestPeriod=$campaign->performanceRecords()->max('period_end');$currentMetrics=$latestPeriod?$campaign->performanceRecords()->where('period_end',$latestPeriod)->pluck('metric_value','metric_key'):collect();$baseline=$campaign->baseline;$baselineMetrics=$baseline?$baseline->metrics()->pluck('metric_value','metric_key'):collect();$latest=$campaign->keywords()->with('latestRanking')->get();$clientOverview=['baseline'=>$baselineMetrics,'current'=>$currentMetrics,'period'=>$latestPeriod,'keywords'=>$latest->count(),'top10'=>$latest->filter(fn($keyword)=>$keyword->latestRanking?->rank_position && $keyword->latestRanking->rank_position<=10)->count(),'completedActivities'=>$campaign->activities()->whereIn('status',['approved','completed'])->count()];$data=['campaign'=>$campaign,'tab'=>$tab,'isClient'=>$isClient,'clientOverview'=>$clientOverview,'cycles'=>$campaign->cycles()->latest('month')->get(),'activities'=>$campaign->activities()->with('assignee')->latest()->get(),'technical'=>SeoTechnicalIssue::where('seo_campaign_id',$campaign->id)->latest()->get(),'backlinks'=>SeoBacklinkActivity::where('seo_campaign_id',$campaign->id)->latest()->get(),'onpage'=>SeoOnPageOptimization::where('seo_campaign_id',$campaign->id)->latest()->get(),'performance'=>$campaign->performanceRecords()->latest('period_end')->get(),'reports'=>$reports->get()];return view('seo.operations.workspace',$data);}
 public function addCycle(Request $r,SeoCampaign $campaign){$this->authorize('manage',$campaign);$d=$r->validate(['month'=>'required|date','objectives'=>'nullable|string|max:5000']);$campaign->cycles()->updateOrCreate(['month'=>date('Y-m-01',strtotime($d['month']))],$d+['created_by'=>auth()->id()]);return back()->with('success','Monthly SEO cycle saved.');}
 public function addActivity(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['seo_monthly_cycle_id'=>'nullable|exists:seo_monthly_cycles,id','category'=>['required',Rule::in(['on_page','technical','content','off_page','local','analytics','reporting','other'])],'title'=>'required|string|max:255','target_url'=>'nullable|url|max:2048','deadline'=>'nullable|date','priority'=>['required',Rule::in(['high','medium','low'])],'assigned_to'=>'nullable|exists:users,id']);$campaign->activities()->create($d);return back()->with('success','SEO activity added.');}
 public function updateActivity(Request $r,SeoCampaign $campaign,SeoActivity $activity){$this->authorize('contribute',$campaign);abort_unless($activity->seo_campaign_id===$campaign->id,404);abort_if(in_array($activity->status,['approved','completed']),422,'Approved activities are locked.');$d=$r->validate(['status'=>['required',Rule::in(['todo','in_progress','submitted'])],'work_notes'=>'nullable|string|max:5000']);$activity->update($d);return back()->with('success',$d['status']==='submitted'?'Activity submitted for manager review.':'Activity updated.');}
 public function reviewActivity(Request $r,SeoCampaign $campaign,SeoActivity $activity){$this->authorize('manage',$campaign);abort_unless($activity->seo_campaign_id===$campaign->id,404);abort_unless($activity->status==='submitted',422,'Only submitted activities can be reviewed.');$d=$r->validate(['decision'=>['required',Rule::in(['approved','changes_required'])],'feedback'=>'nullable|string|max:5000']);$activity->update(['status'=>$d['decision'],'reviewed_by'=>auth()->id(),'reviewed_at'=>now(),'review_feedback'=>$d['feedback']??null,'completed_at'=>$d['decision']==='approved'?now():null]);return back()->with('success',$d['decision']==='approved'?'Activity approved and marked complete.':'Changes requested for this activity.');}
 public function addTechnical(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['title'=>'required|string|max:255','issue_type'=>'required|string|max:50','affected_url'=>'nullable|url|max:2048','severity'=>['required',Rule::in(['critical','high','medium','low'])],'assigned_to'=>'nullable|exists:users,id']);SeoTechnicalIssue::create($d+['seo_campaign_id'=>$campaign->id]);return back()->with('success','Technical issue added.');}
 public function addBacklink(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['activity_type'=>'required|string|max:255','target_website'=>'nullable|url|max:2048','target_url'=>'nullable|url|max:2048','published_url'=>'nullable|url|max:2048','anchor_text'=>'nullable|string|max:255','link_type'=>['required',Rule::in(['dofollow','nofollow','sponsored','ugc','unknown'])],'verification_status'=>['required',Rule::in(['submitted','published','verified','lost','rejected'])]]);SeoBacklinkActivity::create($d+['seo_campaign_id'=>$campaign->id,'assigned_to'=>auth()->id()]);return back()->with('success','Off-page activity recorded.');}
 public function addPerformance(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['period_start'=>'required|date','period_end'=>'required|date|after_or_equal:period_start','source'=>['required',Rule::in(['manual','ga4','search_console','import'])],'metric_key'=>'required|string|max:100','metric_value'=>'nullable|numeric']);SeoPerformanceRecord::updateOrCreate(['seo_campaign_id'=>$campaign->id,'period_start'=>$d['period_start'],'period_end'=>$d['period_end'],'source'=>$d['source'],'metric_key'=>$d['metric_key']],$d+['recorded_by'=>auth()->id(),'recorded_at'=>now()]);return back()->with('success','Performance metric saved.');}
 public function createReport(Request $r,SeoCampaign $campaign){$this->authorize('contribute',$campaign);$d=$r->validate(['title'=>'required|string|max:255','period_start'=>'required|date','period_end'=>'required|date|after_or_equal:period_start','observations'=>'nullable|string|max:10000']);$snapshot=['activities_approved'=>$campaign->activities()->whereIn('status',['approved','completed'])->whereBetween('created_at',[$d['period_start'],$d['period_end'].' 23:59:59'])->count(),'keywords_tracked'=>$campaign->keywords()->count(),'generated_at'=>now()->toIso8601String()];$campaign->reports()->create($d+['prepared_by'=>auth()->id(),'snapshot'=>$snapshot]);return back()->with('success','Historical SEO report draft created.');}
 public function reviewReport(Request $r,SeoCampaign $campaign,SeoReport $report){$this->authorize('manage',$campaign);abort_unless($report->seo_campaign_id===$campaign->id,404);$d=$r->validate(['decision'=>['required',Rule::in(['approved','changes_required','published'])],'feedback'=>'nullable|string|max:5000']);abort_if($d['decision']==='published' && $report->status!=='approved',422,'Approve the report before publishing it.');$report->update(['status'=>$d['decision'],'reviewed_by'=>auth()->id(),'reviewed_at'=>now(),'review_feedback'=>$d['feedback']??null]);return back()->with('success','Report review saved.');}
 private function isClient(): bool { return in_array(strtolower((string) (auth()->user()?->getRawOriginal('role') ?? '')), ['client','customer'], true); }
}
